const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error('job_id must be a valid UUID');
}

return [{ json: { job_id: jobId } }];

const job = $input.first().json;

if (!job.job_exists) {
  throw new Error(`Job ${job.requested_job_id} was not found`);
}

const normalVisualState =
  job.status === 'processing' &&
  ['voiceover', 'visuals'].includes(job.current_stage);

const retryVisualState =
  job.status === 'failed' &&
  job.current_stage === 'visuals';

if (!normalVisualState && !retryVisualState) {
  throw new Error(
    `Job ${job.job_id} is not eligible for visual sourcing: ` +
    `status=${job.status}, current_stage=${job.current_stage}`
  );
}

const requiredScenesByDuration = { 15: 4, 30: 8, 45: 12, 60: 15 };
const requiredSceneCount = requiredScenesByDuration[Number(job.target_duration_seconds)];
if (!requiredSceneCount) throw new Error(`Unsupported target_duration_seconds: ${job.target_duration_seconds}`);
if (!Array.isArray(job.scenes)) throw new Error(`Job ${job.job_id} scenes are unavailable`);
if (Number(job.scene_count) !== requiredSceneCount || job.scenes.length !== requiredSceneCount) throw new Error(`Job ${job.job_id} must have exactly ${requiredSceneCount} scenes`);
const seenQueries = new Set(); let pendingSceneCount=0; let completedSceneCount=0;
for (let index=0; index<job.scenes.length; index++) {
 const scene=job.scenes[index]; const expected=index+1;
 if (Number(scene.scene_number)!==expected) throw new Error(`Invalid scene_number at position ${expected}: received ${scene.scene_number}`);
 for (const field of ['scene_id','narration','visual_description','visual_query']) if (typeof scene[field] !== 'string' || scene[field].trim()==='') throw new Error(`Scene ${expected} is missing ${field}`);
 const query=scene.visual_query.trim(); if (query.length>100) throw new Error(`Scene ${expected} visual_query exceeds 100 characters`);
 const queryKey=query.toLowerCase(); if (seenQueries.has(queryKey)) throw new Error(`Duplicate visual_query at scene ${expected}`); seenQueries.add(queryKey);
 if (!['factual','generic'].includes(scene.visual_subject_type)) throw new Error(`Scene ${expected} has invalid visual_subject_type`);
 const audioPath=typeof scene.audio_path==='string'?scene.audio_path.trim():''; const duration=Number(scene.duration_seconds); if (!audioPath || !Number.isFinite(duration) || duration<=0) throw new Error(`Scene ${expected} does not have completed voiceover`);
 const visualPath=typeof scene.visual_path==='string'?scene.visual_path.trim():''; const assetCount=Number(scene.asset_count??0); if(!Number.isInteger(assetCount)||assetCount<0) throw new Error(`Scene ${expected} has invalid asset_count`);
 if (visualPath) { if(assetCount<1) throw new Error(`Scene ${expected} has visual_path without asset metadata`); completedSceneCount++; } else { if(assetCount!==0) throw new Error(`Scene ${expected} has asset metadata without visual_path`); pendingSceneCount++; }
}
if (job.current_stage==='voiceover' && completedSceneCount>0) throw new Error(`Job ${job.job_id} has visual output before visual stage start`);
const alreadyComplete=pendingSceneCount===0 && completedSceneCount===requiredSceneCount;
if(alreadyComplete && job.current_stage!=='visuals') throw new Error(`Job ${job.job_id} is visually complete but current_stage is ${job.current_stage}`);
return [{json:{...job,required_scene_count:requiredSceneCount,pending_scene_count:pendingSceneCount,completed_scene_count:completedSceneCount,already_complete:alreadyComplete}}];

