WITH transitioned AS (
  UPDATE public.jobs SET current_stage='visuals', updated_at=now() WHERE id=$1::uuid AND status='processing' AND current_stage='voiceover' RETURNING id,status,current_stage
), resumed AS (
  UPDATE public.jobs SET status='processing', current_stage='visuals', last_error=NULL, updated_at=now() WHERE id=$1::uuid AND status='failed' AND current_stage='visuals' RETURNING id,status,current_stage
), existing AS (
  SELECT id,status,current_stage FROM public.jobs WHERE id=$1::uuid AND status='processing' AND current_stage='visuals'
), ready AS (
  SELECT id,status,current_stage,true AS started_now FROM transitioned UNION ALL SELECT id,status,current_stage,true AS started_now FROM resumed UNION ALL SELECT id,status,current_stage,false AS started_now FROM existing LIMIT 1
)
SELECT $1::uuid AS job_id, EXISTS(SELECT 1 FROM ready) AS ready_to_run, (SELECT status FROM ready LIMIT 1) AS status, (SELECT current_stage FROM ready LIMIT 1) AS current_stage, COALESCE((SELECT started_now FROM ready LIMIT 1),false) AS started_now;

